async function seedUserWorkspace(user:AppUser){
  const d1=db(); const timestamp=now(); const suffix=user.userId.replace(/[^a-zA-Z0-9]/g,'').slice(-12);
  const boardRows = [
    [`brd_boats_${suffix}`,user.userId,'Project boats','#b55232','Interesting boats that need some work'],
    [`brd_4x4_${suffix}`,user.userId,'Old 4×4s','#587986','Simple, honest vintage trucks'],
    [`brd_drive_${suffix}`,user.userId,'Worth a drive','#c3943f','Strong enough to inspect in person'],
  ];
  await d1.batch(boardRows.map(row=>d1.prepare(`INSERT INTO boards (id,user_id,name,color,description,created_at) VALUES (?,?,?,?,?,?) ON CONFLICT DO NOTHING`).bind(...row,timestamp)));
  await d1.batch(['lst_cj7','lst_f100','lst_bmw','lst_landrover'].map(listingId=>d1.prepare(`INSERT INTO saved_items (user_id,listing_id,status,created_at) VALUES (?,?,?,?) ON CONFLICT DO NOTHING`).bind(user.userId,listingId,'watching',timestamp)));
  await d1.prepare(`INSERT INTO alerts (id,user_id,name,query,criteria_json,status,match_count,created_at) VALUES (?,?,?,?,?,?,?,?) ON CONFLICT DO NOTHING`).bind(`alt_trucks_${suffix}`,user.userId,'Vintage 4×4s under $25k','pre-1990 four wheel drives under $25,000',json({category:'Cars & trucks',maxPrice:25000,beforeYear:1990,keywords:['4×4','4x4']}),'active',3,timestamp).run();
  await logActivity(user,'system','Zingposts','seed_workspace','workspace',user.userId,'Example workspace created with seeded marketplace data.',false,null);
}

