  const [listings,users,boards,boardItems,saved,alerts,research,conversations,messages,offers,trades,participants,assets,activities,confirmations,agents,preferences,collaborationSessions,collaborationItems] = await Promise.all([
    d1.prepare(`SELECT * FROM listings WHERE status IN ('published','tracked') OR owner_id=? ORDER BY CASE status WHEN 'published' THEN 0 ELSE 1 END, updated_at DESC`).bind(user.userId).all(), d1.prepare(`SELECT id,name,avatar FROM users`).all(), d1.prepare(`SELECT * FROM boards WHERE user_id=? ORDER BY created_at`).bind(user.userId).all(), d1.prepare(`SELECT * FROM board_items WHERE board_id IN (SELECT id FROM boards WHERE user_id=?)`).bind(user.userId).all(), d1.prepare(`SELECT * FROM saved_items WHERE user_id=?`).bind(user.userId).all(), d1.prepare(`SELECT * FROM alerts WHERE user_id=? ORDER BY created_at DESC`).bind(user.userId).all(), d1.prepare(`SELECT * FROM research_notes WHERE user_id=? ORDER BY created_at DESC`).bind(user.userId).all(), d1.prepare(`SELECT * FROM conversations WHERE buyer_id=? OR seller_id=? ORDER BY updated_at DESC`).bind(user.userId,user.userId).all(), d1.prepare(`SELECT * FROM messages WHERE conversation_id IN (SELECT id FROM conversations WHERE buyer_id=? OR seller_id=?) ORDER BY created_at`).bind(user.userId,user.userId).all(), d1.prepare(`SELECT * FROM offers WHERE buyer_id=? OR listing_id IN (SELECT id FROM listings WHERE owner_id=?) ORDER BY updated_at DESC`).bind(user.userId,user.userId).all(), d1.prepare(`SELECT * FROM trade_rooms WHERE creator_id=? ORDER BY created_at DESC`).bind(user.userId).all(), d1.prepare(`SELECT * FROM trade_participants WHERE trade_id IN (SELECT id FROM trade_rooms WHERE creator_id=?)`).bind(user.userId).all(), d1.prepare(`SELECT * FROM trade_assets WHERE trade_id IN (SELECT id FROM trade_rooms WHERE creator_id=?)`).bind(user.userId).all(), d1.prepare(`SELECT * FROM activity_events WHERE user_id=? ORDER BY created_at DESC LIMIT 40`).bind(user.userId).all(), d1.prepare(`SELECT * FROM confirmation_requests WHERE user_id=? ORDER BY created_at DESC`).bind(user.userId).all(), d1.prepare(`SELECT * FROM agent_connections WHERE user_id=? ORDER BY created_at DESC`).bind(user.userId).all(), d1.prepare(`SELECT preferences_json FROM user_preferences WHERE user_id=?`).bind(user.userId).first<{preferences_json:string}>(), d1.prepare(`SELECT * FROM collaboration_sessions WHERE user_id=? ORDER BY updated_at DESC`).bind(user.userId).all(), d1.prepare(`SELECT * FROM collaboration_items WHERE user_id=? ORDER BY created_at`).bind(user.userId).all(),
  ]);
