  return { user, preferences:mergedPreferences, verification:verificationFrom(user), listings:listings.results.map(hydrateListing), users:users.results, boards:boards.results, boardItems:boardItems.results, saved:saved.results.map(hydrateJson), alerts:alerts.results.map(hydrateJson), research:research.results.map(hydrateJson), conversations:conversations.results, messages:messages.results, offers:offers.results, trades:trades.results, participants:participants.results, assets:assets.results.map(hydrateJson), activities:activities.results.map(row=>hydrateJson(row)), confirmations:confirmations.results.map(row=>{const item=hydrateJson(row);return {...item,summary:`Agent wants to ${String(item.action).replaceAll('_',' ')}.`};}), agents:agents.results.map(hydrateJson), collaborationSessions:collaborationSessions.results.map(hydrateJson), collaborationItems:collaborationItems.results.map(hydrateJson) };
