function hydrateJson(row:Record<string,unknown>) {
  const out={...row};
  for (const key of ['criteria_json','sources_json','conditions_json','tags_json','undo_json','payload_json','scopes_json','setup_json','context_json','listing_ids_json','options_json','response_json']) {
    if (!(key in out)) continue;
    if (key==='response_json'&&out[key]==null) { out.response=null; continue; }
    const fallback=key==='sources_json'||key==='conditions_json'||key==='tags_json'||key==='scopes_json'||key==='listing_ids_json'||key==='options_json'?[]:{};
    out[key.replace('_json','')]=parse(out[key],fallback);
  }
  return out;
}
function hydrateListing(row:Record<string,unknown>) { return {...hydrateJson(row),attributes:parse(row.attributes_json,{})}; }

function connectionGuide() {
  return {
    ...AGENT_GUIDE,
    architecture:{...AGENT_GUIDE.architecture,description:'Zingposts stores marketplace state and exposes deterministic tools. Reasoning remains in the user’s external agent.'},
    persistence:{webmcp:'document-scoped',explanation:'A compact core remains registered throughout the application document. Focused business capability packs activate without navigation and should be rediscovered after activation.',durableInZingposts:['user workspace','active safe agent profile and scopes','boards','research','alerts','drafts','activity and undo','account verification state']},
    workspaceReturn:{human:'Prototype work resumes with the same normalized email. Once upgraded, that shortcut is permanently disabled and the person must prove control of the verified email through a Supabase session.',agent:'In the person’s signed-in browser, safe WebMCP work starts without another login. A one-use invite or code is only for a separate browser or unattended access.',whenSignedOut:'Only setup tools are exposed. The agent can prepare a handoff, or the person can sign in; WebMCP tools must be rediscovered after authentication changes.'},
    trustLanes:{setup:'Signed-out agents can inspect setup state and prepare a human handoff, but cannot browse or change marketplace data through WebMCP.',authenticated:'The signed-in browser delegates safe private workspace actions to its outside agent. Independent sessions remain available for unattended work.',consequential:'Publishing or reaching another marketplace participant requires verified workspace ownership plus exact one-time human confirmation.'},
    reconnect:AGENT_GUIDE.returnLater,
    suggestedSkill:{name:'zingposts-operator',purpose:'Return to Zingposts without storing a human login, invite fragment, fallback code, or stale tool catalog.',instructions:AGENT_GUIDE.skillStarter},
    monitoring:'An automation should reopen Zingposts on its schedule, rediscover tools, inspect saved alerts or listings, record any changes, and leave consequential follow-up for human review. Zingposts itself does not run an LLM in the background.'
  };
}

