function capabilityIndex(activeCapability='marketplace',authenticated=false){return {strategy:'persistent_core_plus_activated_capability',activeCapability,totalCatalogTools:WEBMCP_TOOL_NAMES.length,persistentCoreTools:PERSISTENT_CORE_TOOLS,groups:CAPABILITY_AREAS.map(group=>({id:group.id,label:group.label,summary:group.summary,routeTemplate:group.routeTemplate,requiresAuth:group.requiresAuth,access:group.requiresAuth&&!authenticated?'sign_in_required':'available',toolCount:group.tools.length,entryTools:group.entryTools,activeNow:group.id===activeCapability,activationRequired:group.id!==activeCapability})),next:'Call activate_capability with the best capabilityId. This replaces the focused typed tool pack without navigating or changing the person’s view.'};}
