function activateCapability(input:Input,authenticated=false){const capabilityId=String(input.capabilityId??'marketplace');const group=CAPABILITY_AREAS.find(item=>item.id===capabilityId);if(!group)throw invalidInput(`Unknown capability: ${capabilityId}.`,{allowedValues:CAPABILITY_AREAS.map(item=>item.id)});if(group.requiresAuth&&!authenticated)throw new ActionError('AUTHENTICATION_REQUIRED',`${group.label} requires an authenticated workspace.`,{capabilityId});const allowed=authenticated?new Set(WEBMCP_TOOL_NAMES):new Set(PUBLIC_WEBMCP_TOOL_NAMES);return {capabilityId,label:group.label,activeNow:true,registeredAfterRediscovery:[...new Set([...PERSISTENT_CORE_TOOLS,...group.tools])].filter(tool=>allowed.has(tool)),navigationChanged:false,humanViewChanged:false,next:'Rediscover WebMCP tools, then call the focused typed tool you need.'};}
function navigationTarget(input:Input,authenticated=false){const capabilityId=String(input.capabilityId??'marketplace');const group=CAPABILITY_AREAS.find(item=>item.id===capabilityId);if(!group)throw invalidInput(`Unknown capability: ${capabilityId}.`,{allowedValues:CAPABILITY_AREAS.map(item=>item.id)});if(group.requiresAuth&&!authenticated)throw new ActionError('AUTHENTICATION_REQUIRED',`${group.label} requires the human’s signed-in workspace.`,{capabilityId});const listingId=String(input.listingId??'');const boardId=String(input.boardId??'');const sessionId=String(input.sessionId??'');const section=String(input.section??'');if(capabilityId==='listing'&&!listingId)throw invalidInput('listingId is required to open a listing for human review.',{required:['listingId']});let view=capabilityId==='selling'?'mine':capabilityId==='inbox'?'inbox':capabilityId==='trades'?'trades':capabilityId==='connection'?'agent':capabilityId;let path=String(group.routeTemplate);let detailOpen=false;let hash='';if(capabilityId==='marketplace'&&boardId){view=`board:${boardId}`;path=`/boards/${boardId}`;}else if(capabilityId==='listing'){view='browse';detailOpen=true;hash=section==='research'?'#research':'';path=`/listings/${listingId}${hash}`;}else if(capabilityId==='workbench'){path=sessionId?`/workbench/${sessionId}`:'/workbench';}return {capabilityId,view,path,detailOpen,listingId:listingId||null,sessionId:sessionId||null,hash,humanVisible:true,toolsChanged:false,message:`Opened ${group.label} for the person. Business capability activation is unchanged.`};}

async function publicListings() {
  await ensureDatabase(PUBLIC_SEED_USER);
  return (await db().prepare(`SELECT * FROM listings WHERE status IN ('published','tracked') ORDER BY CASE status WHEN 'published' THEN 0 ELSE 1 END, updated_at DESC`).all()).results.map(hydrateListing);
}

export async function getGuestState(setupSessionId='') {
  const listings=await publicListings();
  const pendingSetup=setupSessionId?await getOnboardingStatus(setupSessionId):null;
  return {authenticated:false,authMode:process.env.NODE_ENV==='development'?'local-demo':'zingposts',listings,pendingSetup,publicTools:PUBLIC_WEBMCP_TOOL_NAMES,connectionGuide:connectionGuide()};
}

export async function getOnboardingStatus(setupSessionId:string) {
  await ensureDatabase(PUBLIC_SEED_USER);
  const row=await db().prepare(`SELECT id,initiated_by,agent_name,status,pairing_code,scopes_json,preferences_json,created_at,expires_at,approved_at FROM onboarding_sessions WHERE id=?`).bind(setupSessionId).first<Record<string,unknown>>();
  if(!row) return {found:false,setupSessionId};
  const expired=Date.parse(String(row.expires_at))<Date.now();
  return {...hydrateJson(row),found:true,status:expired&&row.status!=='approved'?'expired':row.status};
}

export async function runPublicAction(action:string,input:Input={}):Promise<any> {
  await ensureDatabase(PUBLIC_SEED_USER);
  if(!PUBLIC_WEBMCP_TOOL_NAMES.includes(action))throw new ActionError('AUTHENTICATION_REQUIRED',`Sign in before using Zingposts action: ${action}`,{action,availableSetupTools:PUBLIC_WEBMCP_TOOL_NAMES});
  if(action==='get_site_capabilities') return siteCapabilities();
  if(action==='get_webmcp_manifest') return webmcpManifest(String(input.activeCapability??'marketplace'));
  if(action==='get_capability_index') return capabilityIndex(String(input.activeCapability??'marketplace'),false);
  if(action==='get_capability_group') return capabilityGroup(String(input.capabilityId??''),false,String(input.activeCapability??'marketplace'));
  if(action==='activate_capability') return activateCapability(input,false);
  if(action==='navigate_to_workspace'||action==='open_for_human_review') return navigationTarget(input,false);
  if(action==='get_connection_guide') return connectionGuide();
  if(action==='get_agent_bootstrap')return {guide:{version:AGENT_GUIDE_VERSION,url:'/for-agents',machineReadableUrl:'/api/agent-guide'},authentication:{authenticated:false,agentAccess:'setup-only'},canonicalAgent:null,workspace:null,attention:{count:0,collaborationItems:[],consequentialActions:[]},activeCollaboration:null,setup:{availableTools:PUBLIC_WEBMCP_TOOL_NAMES,personFirst:'Ask the person to sign in in this browser, then rediscover tools.',agentFirst:'Call start_agent_onboarding and open the returned handoffPath for the person.',independentAccess:'If the person supplied a one-use invite or code, call authenticate_agent.'},next:['Help the person open or resume a workspace.','After authentication changes, rediscover WebMCP tools and call get_agent_bootstrap again.']};
  if(action==='get_auth_status') return {authenticated:false,agentAccess:'public',next:'An agent can use public discovery or prepare a prototype handoff. A verified private workspace requires authenticate_agent with a fresh code issued by the signed-in person.'};
  if(action==='connect_agent') {
    const prepared=await runPublicAction('start_agent_onboarding',input);
    return {...prepared,status:'connected_public',access:'public',approvalRequired:false,humanMessage:`${String(input.agentName??input.name??'Your agent')} is connected to Zingposts’ public marketplace. Sign in through the handoff path to attach its safe workspace profile automatically.`,next:['Use public search and listing tools now.','Open or share the handoffPath when private workspace access is needed.','After sign-in, reopen Zingposts and call connect_agent again to resume safe workspace work.']};
  }
  if(action==='start_agent_onboarding') {
    const setupSessionId=id('setup'); const pairingCode=String(Math.floor(100000+Math.random()*900000)); const createdAt=now(); const expiresAt=new Date(Date.now()+24*60*60*1000).toISOString();
    const agentName=String(input.agentName??input.name??'Local agent'); const scopes=(input.scopes as string[]|undefined)??DEFAULT_AGENT_SCOPES; const preferences=(input.preferences as Record<string,unknown>|undefined)??{};
    await db().prepare(`INSERT INTO onboarding_sessions (id,initiated_by,agent_name,status,pairing_code,scopes_json,preferences_json,created_at,expires_at) VALUES (?,?,?,?,?,?,?,?,?)`).bind(setupSessionId,'agent',agentName,'awaiting_user',pairingCode,json(scopes),json(preferences),createdAt,expiresAt).run();
    return {setupSessionId,pairingCode,status:'awaiting_user',expiresAt,handoffPath:`/?setup=${setupSessionId}`,approvalRequired:false,humanMessage:`${agentName} prepared a Zingposts setup. Open the handoff path and sign in; its safe workspace profile will attach automatically.`,next:['Keep the setupSessionId.','Open or share the handoffPath with the user.','After the user signs in, reopen Zingposts and rediscover its WebMCP tools.']};
  }
  if(action==='get_onboarding_status') return getOnboardingStatus(String(input.setupSessionId??''));
  if(action==='search_marketplace') { const normalized=normalizedSearchInput(input); const listings=await publicListings(); const page=sortedPage(listings.filter((listing:any)=>matchesSearch(listing,normalized)),normalized); return {...page,count:page.total,query:String(normalized.query??''),interpreted:{tokens:searchTokens(String(normalized.query??'')),category:normalized.category??null,filters:{minPrice:normalized.minPrice??null,maxPrice:normalized.maxPrice??null,afterYear:normalized.afterYear??null,beforeYear:normalized.beforeYear??null,condition:normalized.condition??null,location:normalized.location??null},sort:String(normalized.sort??'relevance')}}; }
  if(action==='interpret_alert') { const query=String(input.query??''); const intent=inferredAlertIntent(query,(input.criteria as Record<string,unknown>|undefined)??{}); const criteria=intent.criteria; const preview:any=await runPublicAction('search_marketplace',{...criteria,query:intent.searchQuery,pageSize:12}); return {query,interpretation:{tokens:intent.tokens,searchQuery:intent.searchQuery,criteria,plainLanguage:[criteria.category?`Category: ${criteria.category}`:null,criteria.maxPrice?`Maximum price: $${Number(criteria.maxPrice).toLocaleString()}`:null,criteria.minPrice?`Minimum price: $${Number(criteria.minPrice).toLocaleString()}`:null,criteria.beforeYear?`Built before: ${criteria.beforeYear}`:null,criteria.afterYear?`Built after: ${criteria.afterYear}`:null,criteria.location?`Location: ${criteria.location}`:null,criteria.condition?`Condition: ${criteria.condition}`:null].filter(Boolean)},previewCount:preview.count,matches:preview.results}; }
  if(action==='get_listing'||action==='get_listing_snapshot') { const requestedListingId=String(input.listingId??''); const listing=await db().prepare(`SELECT * FROM listings WHERE id=? AND status IN ('published','tracked')`).bind(requestedListingId).first<Record<string,unknown>>(); if(!listing) throw notFound('Listing',requestedListingId); return {listing:hydrateListing(listing),snapshotAt:now(),sourceAuthoritative:listing.origin_type==='native'}; }
  throw new ActionError('AUTHENTICATION_REQUIRED',`Authentication required for Zingposts action: ${action}`,{action});
}

function webmcpManifest(activeCapability='marketplace'){
  const manifestSeen=new Set<string>(PERSISTENT_CORE_TOOLS);
  const manifestCapabilityGroups=CAPABILITY_AREAS.map(group=>({id:group.id,kind:'capability',description:group.summary,activeNow:group.id===activeCapability,requiresAuth:group.requiresAuth,tools:group.tools.filter(tool=>{if(manifestSeen.has(tool))return false;manifestSeen.add(tool);return true})}));
  return {
    version:'3.0',
    purpose:'A compact discovery map for an outside agent. Use this before scanning the full flat tool list.',
    progressiveDiscovery:{strategy:'persistent_core_plus_activated_capability',activeCapability,totalCatalogTools:WEBMCP_TOOL_NAMES.length,persistentCoreTools:PERSISTENT_CORE_TOOLS,indexTool:'get_capability_index',detailTool:'get_capability_group',activationTool:'activate_capability',humanReviewTool:'open_for_human_review',rediscoveryRule:'After capability activation or authentication changes, enumerate tools again. Navigation does not unlock business tools.'},
    organization:{views:'Change or inspect what the person sees.',queries:'Read marketplace and deal state without changing it.',actions:'Make one explicit, durable workspace change.',workflows:'Compose tools into a multi-step outcome with human confirmation where required.'},
    groups:[
      {id:'persistent_core',kind:'orientation',description:'Stable bootstrap, discovery, authentication, attention, and optional human-review navigation tools.',activeNow:true,tools:PERSISTENT_CORE_TOOLS},
      ...manifestCapabilityGroups,
    ],
    recommendedEntry:['get_agent_bootstrap','activate_capability','get_human_attention_queue'],
    canvasWorkflow:['Call get_agent_bootstrap once.','Activate the relevant focused capability without navigating.','Call start_collaboration_session with the person’s objective.','Use stable resource identifiers for search, research, and organization while the person continues browsing.','Use open_for_human_review only when showing something would help the person.','Call get_collaboration_session after the human responds and continue from durable state.','Leave consequential commerce actions at the human confirmation gate.']
  };
}

