  if(action==='get_capability_index') return capabilityIndex(String(input.activeCapability??'marketplace'),true);
  if(action==='get_capability_group') return capabilityGroup(String(input.capabilityId??''),true,String(input.activeCapability??'marketplace'));
  if(action==='activate_capability') return activateCapability(input,true);
  if(action==='navigate_to_workspace'||action==='open_for_human_review') return navigationTarget(input,true);
  if(action==='approve_agent_onboarding') { const setupSessionId=String(input.setupSessionId??''); const session=await d1.prepare(`SELECT * FROM onboarding_sessions WHERE id=?`).bind(setupSessionId).first<Record<string,unknown>>(); if(!session) throw new Error('Agent setup was not found.'); if(Date.parse(String(session.expires_at))<Date.now()) throw new Error('This setup has expired. Ask the agent to begin again.'); if(session.status==='approved') return {setupSessionId,status:'approved'}; const agentId=`agt_${setupSessionId.replace('setup_','').slice(0,16)}`; const requested=parse<string[]>(session.scopes_json,DEFAULT_AGENT_SCOPES); const scopes=requested.filter(scope=>SAFE_AGENT_SCOPES.includes(scope)); const preferences=parse<Record<string,unknown>>(session.preferences_json,{}); const agentStatus='active'; await d1.prepare(`INSERT INTO agent_connections (id,user_id,name,status,scopes_json,pairing_code,setup_json,created_at,last_seen_at) VALUES (?,?,?,?,?,?,?,?,?) ON CONFLICT (id) DO UPDATE SET user_id=EXCLUDED.user_id,name=EXCLUDED.name,status=EXCLUDED.status,scopes_json=EXCLUDED.scopes_json,pairing_code=EXCLUDED.pairing_code,setup_json=EXCLUDED.setup_json,last_seen_at=EXCLUDED.last_seen_at`).bind(agentId,user.userId,String(session.agent_name),agentStatus,json(scopes),null,json(preferences),timestamp,timestamp).run(); await d1.prepare(`UPDATE onboarding_sessions SET status='approved',claimed_by_user_id=?,approved_at=? WHERE id=?`).bind(user.userId,timestamp,setupSessionId).run(); if((preferences as Record<string,unknown>).interface) await runAction(user,'set_interface_preferences',{preferences:(preferences as Record<string,unknown>).interface},{type:'system',name:'Zingposts'}); await logActivity(user,'system','Zingposts',action,'agent',agentId,`Attached ${String(session.agent_name)} to this browser workspace with ${scopes.length} safe capabilities. Independent access still requires a one-use invite or code.`,true,{action:'revoke_agent',agentId}); return {setupSessionId,agentId,status:agentStatus,scopes,approvalRequired:false,agentAuthenticationRequired:false,access:'browser-delegated',preferencesApplied:Object.keys(preferences).length>0}; }
  if (action==='get_interface_preferences') { const row=await d1.prepare(`SELECT preferences_json FROM user_preferences WHERE user_id=?`).bind(user.userId).first<{preferences_json:string}>(); return {preferences:{...DEFAULT_INTERFACE_PREFERENCES,...parse(row?.preferences_json,DEFAULT_INTERFACE_PREFERENCES)}}; }
  if (action==='get_marketplace_view') { const row=await d1.prepare(`SELECT preferences_json FROM user_preferences WHERE user_id=?`).bind(user.userId).first<{preferences_json:string}>(); const preferences={...DEFAULT_INTERFACE_PREFERENCES,...parse(row?.preferences_json,DEFAULT_INTERFACE_PREFERENCES)}; return {view:{mode:preferences.browseView,category:preferences.browseCategory,filtersExpanded:preferences.filtersExpanded,controlSurface:'left-rail'},availableModes:['gallery','focus','thumbnails'],actions:{openDetails:'get_listing',organize:'add_listings_to_board',save:'save_listing',changeView:'set_marketplace_view'},humanEquivalent:{organize:'drag an item to a board in the left rail'}}; }
  if (action==='set_interface_preferences'||action==='set_navigation_collapsed'||action==='set_marketplace_view') { const row=await d1.prepare(`SELECT preferences_json FROM user_preferences WHERE user_id=?`).bind(user.userId).first<{preferences_json:string}>(); const previous={...DEFAULT_INTERFACE_PREFERENCES,...parse(row?.preferences_json,DEFAULT_INTERFACE_PREFERENCES)}; let requested:Record<string,unknown>; if(action==='set_navigation_collapsed') requested={sidebarCollapsed:Boolean(input.collapsed)}; else if(action==='set_marketplace_view'){ const mode=String(input.mode??previous.browseView); if(!['gallery','focus','thumbnails'].includes(mode)) throw new Error('Marketplace view must be gallery, focus, or thumbnails.'); requested={browseView:mode,browseCategory:String(input.category??previous.browseCategory),filtersExpanded:typeof input.filtersExpanded==='boolean'?input.filtersExpanded:previous.filtersExpanded}; } else requested=(input.preferences as Record<string,unknown>|undefined)??input; const preferences={...previous,...requested,detailView:'fullscreen',openDetailsOnCardClick:true}; await d1.prepare(`INSERT INTO user_preferences (user_id,preferences_json,updated_at) VALUES (?,?,?) ON CONFLICT (user_id) DO UPDATE SET preferences_json=EXCLUDED.preferences_json,updated_at=EXCLUDED.updated_at`).bind(user.userId,json(preferences),timestamp).run(); const summary=action==='set_marketplace_view'?`Set marketplace canvas to ${preferences.browseView}, category ${preferences.browseCategory}, with filters ${preferences.filtersExpanded?'expanded':'collapsed'}.`:`Updated durable interface preferences.`; await logActivity(user,actorType,actorName,action,'interface',user.userId,summary,true,{action:'restore_interface_preferences',preferences:previous}); return {preferences,view:{mode:preferences.browseView,category:preferences.browseCategory,filtersExpanded:preferences.filtersExpanded}}; }
