    const activeAgent=actorAgentId?await d1.prepare(`SELECT id FROM agent_connections WHERE id=? AND user_id=? AND status='active'`).bind(actorAgentId,user.userId).first<{id:string}>():await d1.prepare(`SELECT id FROM agent_connections WHERE user_id=? AND name=? AND status='active' ORDER BY last_seen_at DESC LIMIT 1`).bind(user.userId,agentName).first<{id:string}>();
    const context={listingIds:(input.listingIds as string[]|undefined)??[],boardId:input.boardId??null,query:input.query??null,constraints:input.constraints??{}};
